SELECT COUNT(*) FROM users as u, comments as c, posts as p, postHistory as ph WHERE u.Id = c.UserId AND u.Id = ph.UserId AND u.Id = p.OwnerUserId AND u.Views>=0 AND u.Views<=75 AND c.CreationDate>='2010-07-31 05:18:59'::timestamp AND c.CreationDate<='2014-09-12 07:59:13'::timestamp AND p.Score>=-2 AND p.ViewCount>=0 AND p.ViewCount<=18281 AND ph.PostHistoryTypeId=2;